for fn, reps in replacements.items():
    p = Path(fn)
    text = p.read_text(encoding='utf-8')
    for old, new in reps:
        n = text.count(old)
        if n != 1:
            raise SystemExit(f'{fn}: expected one target, found {n}: {old[:120]}')
        text = text.replace(old, new, 1)
    p.write_text(text, encoding='utf-8')
print('Corrected final Module 02 explainability refinements applied.')
